  if (sort === "price-asc") favoriteMatches.sort((a, b) => a.price - b.price); else if (sort === "price-desc") favoriteMatches.sort((a, b) => b.price - a.price); else if (sort === "new") favoriteMatches.sort((a, b) => b.createdAt.localeCompare(a.createdAt));
